    """Check if brackets in the string are balanced and properly nested.
    Supports parentheses (), square brackets [], and curly braces {}.
    Ignores all other characters.
    """
    # Mapping of closing to opening brackets
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    stack = []
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
