def solve(grid):
    # Defensive: if grid is not a list of lists, return 0
    if not isinstance(grid, list) or not grid:
        return 0
    # Ensure first row is list
    if not isinstance(grid[0], list):
        return 0
    n = len(grid)
    m = len(grid[0])
    visited = [[False]*m for _ in range(n)]
    count = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                stack = [(i,j)]
                visited[i][j] = True
                while stack:
                    x,y = stack.pop()
                    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                        nx, ny = x+dx, y+dy
                        if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and grid[nx][ny] == 1:
                            visited[nx][ny] = True
                            stack.append((nx,ny))
    return count

