def solve(nums):
    """Return length of the longest strictly increasing subsequence.
    Uses patience sorting O(n log n).
    """
    import bisect
    tails = []
    for x in nums:
        # Find position to replace: first element >= x
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

