def solve(tokens):
    stack = []
    def trunc_div(a, b):
        # Truncate toward zero without using float division
        if b == 0:
            raise ZeroDivisionError('division by zero')
        q = abs(a) // abs(b)
        return q if (a * b) >= 0 else -q
    for token in tokens:
        if token not in '+-*/':
            stack.append(int(token))
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # '/'
                stack.append(trunc_div(a, b))
    return stack[0] if stack else 0

